// n8n Code node: "FIFO Match + Time Test"
// Mode: Run Once for All Items
// Reads:  $('Parse Import').all()       -> new transactions from this file
//         $('Get existing lots').all()  -> ALL rows of Data Table "tax_lots" (Return All = ON!)
// Output items tagged with _op for the Switch node:
//   lot_upsert  -> tax_lots Upsert (match broker + ident + purchase_date, ALL conditions)
//   lot_delete  -> tax_lots Delete (match broker + ident + purchase_date, ALL conditions)
//   sale / dividend / withholding -> CZK conversion branch
//
// One lot = one (broker, ident, purchase_date). Several buys on the same day are merged
// into one lot, because the Data Table key can't tell them apart anyway.

const newTx = $('Parse Import').all().map(i => i.json);
// De-duplicate: a Data Table "Get" node runs once per incoming item, so the same rows can
// arrive many times. Each lot row must be used once.
const seenLots = new Set();
const existingLots = $('Get existing lots').all().map(i => i.json)
  .filter(l => l.ident && l.purchase_date && Number(l.qty_remaining) > 0)
  .filter(l => {
    const k = l.id != null ? `id:${l.id}` : `${l.broker}|${l.ident}|${l.purchase_date}`;
    if (seenLots.has(k)) return false;
    seenLots.add(k);
    return true;
  });

function timeTestOk(purchaseDate, sellDate) {
  const p = new Date(purchaseDate), s = new Date(sellDate);
  const threshold = new Date(p); threshold.setFullYear(p.getFullYear() + 3);
  return s >= threshold;
}

const key = (broker, ident) => `${broker}|${ident}`;
const groups = {};
const group = (broker, ident) => (groups[key(broker, ident)] ||= { broker, ident, lots: [], events: [] });

for (const l of existingLots) {
  group(l.broker, l.ident).lots.push({
    inDb: true, qty: Number(l.qty_remaining), date: l.purchase_date,
    cost: Number(l.cost_native), currency: l.currency, ticker: l.ticker, touched: false,
  });
}
for (const tx of newTx) {
  if (!['buy', 'sell', 'split_close', 'split_open'].includes(tx.kind)) continue;
  group(tx.broker, tx.ident).events.push(tx);
}

const results = [];
const errors = [];

for (const g of Object.values(groups)) {
  const queue = g.lots.sort((a, b) => a.date.localeCompare(b.date));
  g.events.sort((a, b) => a.date.localeCompare(b.date)); // stable: same-day order from the file is kept
  const deleted = [];
  let pendingSplit = null;

  function addLot(lot) {
    const same = queue.find(q => q.date === lot.date && q.currency === lot.currency);
    if (same) { same.qty += lot.qty; same.cost += lot.cost; same.touched = true; return; }
    queue.push({ ...lot, touched: true });
    queue.sort((a, b) => a.date.localeCompare(b.date));
  }

  function consume(qty) {
    let need = qty; const used = [];
    while (need > 1e-9 && queue.length) {
      const lot = queue[0];
      const take = Math.min(lot.qty, need);
      const part = (lot.cost / lot.qty) * take;
      used.push({ date: lot.date, qty: take, cost: part, currency: lot.currency });
      lot.qty -= take; lot.cost -= part; lot.touched = true; need -= take;
      if (lot.qty <= 1e-9) { queue.shift(); if (lot.inDb) deleted.push(lot); }
    }
    return { used, missing: need > 1e-6 ? need : 0 };
  }

  for (const ev of g.events) {
    if (ev.kind === 'buy') {
      addLot({ qty: ev.qty, date: ev.date, cost: ev.amount, currency: ev.currency, ticker: ev.ticker });
    } else if (ev.kind === 'split_close') {
      const { used, missing } = consume(ev.qty);
      if (missing) errors.push(`${g.broker} ${ev.ticker}: split ${ev.date} needs ${ev.qty}, missing ${missing.toFixed(6)} shares`);
      pendingSplit = used;
    } else if (ev.kind === 'split_open') {
      const used = pendingSplit || [];
      const cost = used.reduce((s, c) => s + c.cost, 0);
      const earliest = used.length ? used.map(u => u.date).sort()[0] : ev.date;
      addLot({ qty: ev.qty, date: earliest, cost, currency: used[0]?.currency || ev.currency, ticker: ev.ticker });
      pendingSplit = null;
    } else if (ev.kind === 'sell') {
      const { used, missing } = consume(ev.qty);
      if (missing) {
        errors.push(`${g.broker} ${ev.ticker}: sell ${ev.date} of ${ev.qty} shares, only ${(ev.qty - missing).toFixed(6)} found in tax_lots`);
        continue;
      }
      for (const u of used) {
        results.push({ json: {
          _op: 'sale', year: Number(ev.date.slice(0, 4)), broker: g.broker, ticker: ev.ticker,
          sell_date: ev.date, purchase_date: u.date, qty: u.qty,
          cost_native: u.cost, cost_currency: u.currency,
          proceeds_native: ev.amount * (u.qty / ev.qty), proceeds_currency: ev.currency,
          fee_native: (ev.fee || 0) * (u.qty / ev.qty),   // sell commission / FX fee, same currency as proceeds
          time_test_passed: timeTestOk(u.date, ev.date),
        }});
      }
    }
  }

  for (const lot of deleted) {
    results.push({ json: { _op: 'lot_delete', broker: g.broker, ident: g.ident, purchase_date: lot.date } });
  }
  for (const lot of queue) {
    if (lot.touched && lot.qty > 1e-9) {
      results.push({ json: {
        _op: 'lot_upsert', broker: g.broker, ident: g.ident, ticker: lot.ticker,
        purchase_date: lot.date, qty_remaining: lot.qty, cost_native: lot.cost, currency: lot.currency,
      }});
    }
  }
}

if (errors.length) {
  throw new Error(
    'Not enough purchase lots for some sells - nothing was written. Check that "Get existing lots" ' +
    'has Return All ON and that older files were imported first.\n' + errors.join('\n')
  );
}

for (const tx of newTx) {
  if (tx.kind === 'dividend') results.push({ json: { _op: 'dividend', ...tx } });
  if (tx.kind === 'withholding') results.push({ json: { _op: 'withholding', ...tx } });
  if (tx.kind === 'interest') results.push({ json: { _op: 'interest', ...tx } });
}

return results;

// n8n Code node: "Parse Import"
// Mode: Run Once for All Items (required for `this.helpers`)
// Input: 1 item with binary.data = downloaded CSV file (T212 export OR IBKR Activity Statement)
// Output: array of normalized transaction items

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
let text = buffer.toString('utf-8');
text = text.replace(/^﻿/, ''); // strip UTF-8 BOM that T212/IBKR exports often start with
const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);

const out = [];
const unknown = {};   // rows the bot does not understand -> shown as a warning in Telegram

function parseCsvLine(line) {
  const vals = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { inQ = !inQ; continue; }
    if (c === ',' && !inQ) { vals.push(cur); cur = ''; continue; }
    cur += c;
  }
  vals.push(cur);
  return vals;
}

if (lines[0].includes('Action,Time')) {
  // ---- Trading 212 export ----
  const header = parseCsvLine(lines[0]);
  const idx = name => header.indexOf(name);
  const interestByMonth = {};
  const BUY = /^(market|limit|stop|stop limit) buy$/i;
  const SELL = /^(market|limit|stop|stop limit) sell$/i;
  // rows that carry no taxable event
  const IGNORE = new Set(['Deposit', 'Withdrawal', 'Currency conversion', 'Card debit', 'Card credit']);
  for (let i = 1; i < lines.length; i++) {
    const v = parseCsvLine(lines[i]);
    const action = v[idx('Action')];
    const ident = v[idx('ISIN')] || v[idx('Ticker')];
    const ticker = v[idx('Ticker')];
    const date = (v[idx('Time (UTC)')] || '').split(' ')[0];
    const shares = parseFloat(v[idx('No. of shares')]) || 0;
    const result = v[idx('Result')] ? parseFloat(v[idx('Result')]) : null;
    const total = parseFloat(v[idx('Total')]) || 0;
    const totalCurr = v[idx('Currency (Total)')];
    const whTax = parseFloat(v[idx('Withholding tax')]) || 0;
    const whCurr = v[idx('Currency (Withholding tax)')];
    const fxFee = idx('Currency conversion fee') >= 0 ? (parseFloat(v[idx('Currency conversion fee')]) || 0) : 0;
    const rec = { broker: 'T212', ident, ticker, isin: v[idx('ISIN')] || '', date, qty: shares, amount: total,
                  currency: totalCurr, wh_tax: whTax, wh_curr: whCurr, result };
    if (BUY.test(action)) {
      out.push({ ...rec, kind: 'buy' });                       // Total already includes the FX fee
    } else if (SELL.test(action)) {
      // Total = proceeds AFTER the FX fee -> revenue is Total + fee, the fee is a deductible cost
      out.push({ ...rec, kind: 'sell', amount: total + fxFee, fee: fxFee });
    } else if (action.startsWith('Dividend') && !/return of capital/i.test(action)) {
      out.push({ ...rec, kind: 'dividend' });
    } else if (action === 'Stock split close') {
      out.push({ ...rec, kind: 'split_close' });
    } else if (action === 'Stock split open') {
      out.push({ ...rec, kind: 'split_open' });
    } else if (action === 'Custom stock distribution') {
      out.push({ ...rec, kind: 'buy' });                       // received shares, cost = Total (usually 0)
    } else if (action === 'Interest on cash' || action === 'Lending interest') {
      // daily tiny amounts -> summed per month (see below)
      const key = `${date.slice(0, 7)}|${totalCurr}`;
      const m = (interestByMonth[key] ||= { amount: 0, date, currency: totalCurr });
      m.amount += total;
      if (date > m.date) m.date = date;
    } else if (!IGNORE.has(action)) {
      unknown[`T212: ${action}`] = (unknown[`T212: ${action}`] || 0) + 1;
    }
  }
  // Interest: one record per month, dated on the last interest day of that month
  for (const m of Object.values(interestByMonth)) {
    out.push({ broker: 'T212', ident: 'CASH', ticker: 'CASH', date: m.date,
               amount: Math.round(m.amount * 100) / 100, currency: m.currency, kind: 'interest' });
  }
} else if (lines[0].includes('Statement,Header')) {
  // ---- IBKR Activity Statement ----
  const WATCH = new Set(['Corporate Actions', 'Transfers', 'Option Exercises', 'Bond Interest Received']);
  for (const line of lines) {
    const v = parseCsvLine(line);
    const section = v[0], rtype = v[1];
    if (section === 'Trades' && rtype === 'Data' && v[3] === 'Stocks' && v.length >= 15) {
      const currency = v[4], symbol = v[5];
      const date = (v[6] || '').split(',')[0].trim();
      const qty = parseFloat(v[7]);
      const proceeds = parseFloat(v[10]) || 0;
      const comm = Math.abs(parseFloat(v[11]) || 0);
      const basis = parseFloat(v[12]) || 0;               // buys: price + commission
      const realizedPl = parseFloat(v[13]) || 0;
      if (qty > 0) {
        out.push({ broker: 'IBKR', ident: symbol, ticker: symbol, date, qty,
                   amount: basis, currency, kind: 'buy' });
      } else {
        out.push({ broker: 'IBKR', ident: symbol, ticker: symbol, date, qty: -qty,
                   amount: proceeds, fee: comm, currency, kind: 'sell', result: realizedPl });
      }
    } else if (section === 'Trades' && rtype === 'Data' && v[3] && v[3] !== 'Stocks' && v[3] !== 'Forex') {
      unknown[`IBKR Trades: ${v[3]}`] = (unknown[`IBKR Trades: ${v[3]}`] || 0) + 1;
    } else if (section === 'Dividends' && rtype === 'Data' && v.length >= 6 && !String(v[2]).startsWith('Total')) {
      const m = v[4].match(/^([A-Z0-9.]+)\(/), isin = (v[4].match(/\(([A-Z]{2}[A-Z0-9]{9}\d)\)/) || [])[1] || '';
      out.push({ broker: 'IBKR', ident: m ? m[1] : v[4], ticker: m ? m[1] : v[4], isin,
                 date: v[3], amount: parseFloat(v[5]) || 0, currency: v[2], kind: 'dividend' });
    } else if (section === 'Withholding Tax' && rtype === 'Data' && v.length >= 6 && !String(v[2]).startsWith('Total')) {
      const m = v[4].match(/^([A-Z0-9.]+)\(/), isin = (v[4].match(/\(([A-Z]{2}[A-Z0-9]{9}\d)\)/) || [])[1] || '';
      out.push({ broker: 'IBKR', ident: m ? m[1] : v[4], ticker: m ? m[1] : v[4], isin,
                 date: v[3], amount: parseFloat(v[5]) || 0, currency: v[2], kind: 'withholding' });
    } else if (section === 'Interest' && rtype === 'Data' && v.length >= 6 && !String(v[2]).startsWith('Total')) {
      out.push({ broker: 'IBKR', ident: 'CASH', ticker: 'CASH', date: v[3],
                 amount: parseFloat(v[5]) || 0, currency: v[2], kind: 'interest' });
    } else if (WATCH.has(section) && rtype === 'Data' && !String(v[2]).startsWith('Total')) {
      unknown[`IBKR: ${section}`] = (unknown[`IBKR: ${section}`] || 0) + 1;
    }
  }
} else {
  const preview = JSON.stringify(lines[0] || '').slice(0, 200);
  throw new Error(`Unrecognized file format. First line preview: ${preview}`);
}

// Splits that the T212 export does NOT contain as "Stock split" rows.
// Quantities traded before the split date are scaled so they match post-split shares;
// money amounts stay the same, so cost basis and purchase dates are unchanged.
const MISSING_SPLITS = [
  { broker: 'T212', ident: 'US67066G1040', date: '2024-06-10', ratio: 10 }, // NVIDIA 10:1
];
for (const s of MISSING_SPLITS) {
  const fileHasSplit = out.some(r => r.broker === s.broker && r.ident === s.ident && r.kind.startsWith('split'));
  if (fileHasSplit) continue;
  for (const r of out) {
    if (r.broker === s.broker && r.ident === s.ident && r.date < s.date && (r.kind === 'buy' || r.kind === 'sell')) {
      r.qty = r.qty * s.ratio;
    }
  }
}

// ---- Period covered by this file (used by "Check period overlap") ----
const MONTHS = { January: '01', February: '02', March: '03', April: '04', May: '05', June: '06',
  July: '07', August: '08', September: '09', October: '10', November: '11', December: '12' };
const toIso = s => { const m = s.match(/([A-Za-z]+) (\d{1,2}), (\d{4})/); return m ? `${m[3]}-${MONTHS[m[1]]}-${m[2].padStart(2, '0')}` : null; };
const broker = lines[0].includes('Action,Time') ? 'T212' : 'IBKR';
let periodFrom = null, periodTo = null, periodSource = 'transactions';
if (broker === 'IBKR') {
  const p = lines.find(l => l.startsWith('Statement,Data,Period,'));
  if (p) {
    const [a, b] = parseCsvLine(p)[3].split(' - ');
    periodFrom = toIso(a); periodTo = toIso(b || a); periodSource = 'statement';
  }
} else {
  let fileName = '';
  try { fileName = $('Telegram Trigger').first().json.message.document.file_name || ''; } catch (e) {}
  const m = fileName.match(/from_(\d{4}-\d{2}-\d{2})_to_(\d{4}-\d{2}-\d{2})/);
  if (m) { periodFrom = m[1]; periodTo = m[2]; periodSource = 'file name'; }
}
if (!periodFrom || !periodTo) {
  const dates = out.map(r => r.date).filter(Boolean).sort();
  periodFrom = dates[0] || null; periodTo = dates[dates.length - 1] || null;
}
out.unshift({ kind: 'meta', broker, period_from: periodFrom, period_to: periodTo, period_source: periodSource, unknown });

return out.map(rec => ({ json: rec }));

// n8n Code node: "Collect dates needing CNB rate"
// Place right after "FIFO Match + Time Test". Looks at sale/dividend/withholding items,
// finds every (date, currency) it will need to convert, and checks which are
// NOT already in the "cnb_rate_cache" Data Table -- those get fetched.

const events = $('FIFO Match + Time Test').all().map(i => i.json)
  .filter(e => ['sale', 'dividend', 'withholding', 'interest'].includes(e._op));
const cached = $('Get rate cache').all().map(i => i.json);
const cachedKeys = new Set(cached.map(r => `${r.date}|${r.currency}`));

const needed = new Map(); // key -> {date, currency}
function add(date, currency) {
  if (!date || !currency || currency === 'CZK') return;
  const key = `${date}|${currency}`;
  if (!cachedKeys.has(key)) needed.set(key, { date, currency });
}

for (const ev of events) {
  if (ev._op === 'sale') {
    add(ev.sell_date, ev.proceeds_currency);
    add(ev.purchase_date, ev.cost_currency);
  } else {
    add(ev.date, ev.currency);
    if (ev.wh_tax && ev.wh_curr) add(ev.date, ev.wh_curr); // T212 dividend withholding currency
  }
}

// one item per DATE (not per currency) -- the CNB daily file returns all currencies at once
const byDate = new Map();
for (const { date } of needed.values()) {
  if (!byDate.has(date)) {
    const [y, m, d] = date.split('-');
    byDate.set(date, { date, cnb_date_param: `${d}.${m}.${y}` });
  }
}

// Never return zero items: an empty output would stop the workflow here (no YTD update,
// no Telegram message, lots never written). If every rate is already cached, fetch
// today's rates once instead - harmless, and the loop runs through to the end.
if (byDate.size === 0) {
  const today = new Date().toISOString().slice(0, 10);
  const [y, m, d] = today.split('-');
  byDate.set(today, { date: today, cnb_date_param: `${d}.${m}.${y}` });
}

return [...byDate.values()].map(j => ({ json: j }));
// -> feed into a "Split In Batches" (size 1) + HTTP Request node:
//    GET https://www.cnb.cz/cs/financni-trhy/devizovy-trh/kurzy-devizoveho-trhu/kurzy-devizoveho-trhu/denni_kurz.txt?date={{$json.cnb_date_param}}
//    Response Format: Text
//    then a Code node "Parse CNB response" (next file) -> Data Table "cnb_rate_cache" Insert row

// n8n Code node: "Parse CNB response"
// Place right after the HTTP Request node that fetched denni_kurz.txt for ONE date.
// Input item carries both the HTTP response body (text) and the original date
// (use $('Collect dates needing CNB rate').item.json.date if the HTTP node loses it,
// or just read $json.data / $json.body depending on your n8n version's HTTP Request output field).

const body = $json.data || $json.body || $json;
const text = typeof body === 'string' ? body : JSON.stringify(body);
const lines = text.split(/\r?\n/);
// format:  COUNTRY|CURRENCY_NAME|AMOUNT|CODE|RATE   e.g.  EMU|euro|1|EUR|24,275
const date = $('Collect dates needing CNB rate').item.json.date; // YYYY-MM-DD

const out = [];
for (const line of lines) {
  const parts = line.split('|');
  if (parts.length !== 5) continue;
  const [, , amount, code, rateStr] = parts;
  const rate = parseFloat(rateStr.replace(',', '.')) / parseFloat(amount);
  if (['EUR', 'USD', 'GBP'].includes(code)) { // extend this list if you trade other currencies
    out.push({ json: { date, currency: code, rate } });
  }
}
return out;
// -> wire straight into Data Table "cnb_rate_cache": Insert row

// n8n Code node: "To CZK + Update YTD"
// Reads: $('FIFO Match + Time Test').all()  sale / dividend / withholding items
//        $('Get rate cache final').all()    {date, currency, rate}  (Return All = ON)
//        $('Get YTD row').all()             tax_ytd rows             (Return All = ON)
// tax_ytd columns: year, sales_revenue_czk, dividend_czk, withholding_czk, interest_czk
// Output (all writes happen after this node, in Switch1):
//   _op 'lot_upsert' / 'lot_delete'  passed through from FIFO     -> tax_lots Upsert / Delete
//   one  _op 'ytd_upsert'      per tax year touched by this file  -> tax_ytd Upsert (match year)
//   many _op 'sale_detail'                                        -> tax_sales Insert
//   many _op 'income_detail'  dividends / withholding / interest  -> tax_income Insert
//   one  _op 'telegram_summary'                                   -> Build Telegram Summary + Mark file processed
//
// Every event is booked to the year of ITS OWN date (IBKR statements contain withholding
// corrections for the previous year).
// Dividends are booked GROSS: IBKR dividend rows are already gross; T212 "Total" is net
// (after US withholding), so the T212 withholding (wh_tax / wh_curr) is added back.
// withholding_czk is stored as a negative number (tax paid abroad; refunds are positive).

const events = $('FIFO Match + Time Test').all().map(i => i.json)
  .filter(e => ['sale', 'dividend', 'withholding', 'interest'].includes(e._op));

const rateMap = {};
for (const r of $('Get rate cache final').all().map(i => i.json)) {
  (rateMap[r.date] ||= {})[r.currency] = Number(r.rate);
}
function rate(date, currency) {
  if (currency === 'CZK') return 1;
  const r = rateMap[date]?.[currency];
  if (r === undefined) throw new Error(`Missing CNB rate for ${currency} on ${date} -- fetch it first`);
  return r;
}

const years = {};
const Y = y => (years[y] ||= { revenue: 0, gain: 0, dividend: 0, withholding: 0, interest: 0, sales: 0 });
const saleDetails = [];
const income = [];   // one row per dividend / withholding / interest -> tax_income
const r2 = n => Math.round(n * 100) / 100;
function incomeRow(year, ev, type, amount, currency, czk, note) {
  const isin = ev.isin || '';
  return { _op: 'income_detail', year, broker: ev.broker, type, ticker: ev.ticker || '', isin,
           country: isin ? isin.slice(0, 2) : '', date: ev.date, amount: r2(amount), currency,
           amount_czk: r2(czk), note };
}

for (const ev of events) {
  if (ev._op === 'sale') {
    const y = Y(Number(ev.sell_date.slice(0, 4)));
    const proceeds = ev.proceeds_native * rate(ev.sell_date, ev.proceeds_currency);
    // cost = purchase price (incl. buy fees) + fees paid on the sale
    const cost = ev.cost_native * rate(ev.purchase_date, ev.cost_currency)
               + (ev.fee_native || 0) * rate(ev.sell_date, ev.proceeds_currency);
    y.revenue += proceeds; y.gain += proceeds - cost; y.sales += 1;
    saleDetails.push({ ...ev, proceeds_czk: proceeds, cost_czk: cost, gain_czk: proceeds - cost });
  } else if (ev._op === 'dividend') {
    const yr = Number(ev.date.slice(0, 4)), y = Y(yr);
    const r = rate(ev.date, ev.currency);
    let gross = ev.amount * r;
    if (ev.wh_tax && ev.wh_curr) {                    // T212: Total is net -> add back tax withheld abroad
      const wh = Math.abs(ev.wh_tax) * rate(ev.date, ev.wh_curr);
      gross += wh;
      y.withholding -= wh;
      income.push(incomeRow(yr, ev, 'withholding', -Math.abs(ev.wh_tax), ev.wh_curr, -wh, ''));
    }
    y.dividend += gross;
    income.push(incomeRow(yr, ev, 'dividend', ev.amount, ev.currency, gross,
      ev.wh_tax ? 'T212: amount = net; amount_czk = gross (net + withholding)' : ''));
  } else if (ev._op === 'interest') {                // interest on cash (T212 summed per month)
    const yr = Number(ev.date.slice(0, 4)), czk = ev.amount * rate(ev.date, ev.currency);
    Y(yr).interest += czk;
    income.push(incomeRow(yr, ev, 'interest', ev.amount, ev.currency, czk, ev.broker === 'T212' ? 'monthly sum' : ''));
  } else if (ev._op === 'withholding') {             // IBKR: negative = paid, positive = refund
    const yr = Number(ev.date.slice(0, 4)), czk = ev.amount * rate(ev.date, ev.currency);
    Y(yr).withholding += czk;
    income.push(incomeRow(yr, ev, 'withholding', ev.amount, ev.currency, czk, ''));
  }
}

const ytdRows = $('Get YTD row').all().map(i => i.json).filter(r => r.year);
const THRESHOLD = 100000;
const round = n => Math.round(n);
const out = [];
const yearSummaries = [];

for (const yr of Object.keys(years).map(Number).sort()) {
  const t = years[yr];
  const ex = ytdRows.find(r => Number(r.year) === yr) || {};
  const ytd = {
    year: yr,
    sales_revenue_czk: Number(ex.sales_revenue_czk || 0) + t.revenue,
    dividend_czk: Number(ex.dividend_czk || 0) + t.dividend,
    withholding_czk: Number(ex.withholding_czk || 0) + t.withholding,
    interest_czk: Number(ex.interest_czk || 0) + t.interest,
  };
  out.push({ json: { _op: 'ytd_upsert', ...ytd } });
  yearSummaries.push({
    year: yr,
    sales_count: t.sales,
    this_import_revenue_czk: round(t.revenue),
    this_import_gain_czk: round(t.gain),
    this_import_dividend_czk: round(t.dividend),
    this_import_withholding_czk: round(t.withholding),
    this_import_interest_czk: round(t.interest),
    ytd_revenue_czk: round(ytd.sales_revenue_czk),
    ytd_dividend_czk: round(ytd.dividend_czk),
    ytd_withholding_czk: round(ytd.withholding_czk),
    ytd_interest_czk: round(ytd.interest_czk),
    ytd_remaining_to_100k: round(THRESHOLD - ytd.sales_revenue_czk),
    exemption_still_possible: ytd.sales_revenue_czk <= THRESHOLD,
  });
}

const meta = $('Parse Import').all().map(i => i.json).find(r => r.kind === 'meta') || {};
out.push({ json: {
  _op: 'telegram_summary',
  unknown: meta.unknown || {},
  years: yearSummaries,
  sales: saleDetails.map(s => ({
    ticker: s.ticker, bought: s.purchase_date, sold: s.sell_date,
    gain_czk: round(s.gain_czk), time_test_passed: s.time_test_passed,
  })),
}});

// Lot changes from FIFO are passed through and written LAST (via Switch1), so nothing is
// written to tax_lots unless the whole CZK calculation succeeded.
for (const i of $('FIFO Match + Time Test').all()) {
  if (i.json._op === 'lot_upsert' || i.json._op === 'lot_delete') out.push({ json: i.json });
}

for (const row of income) out.push({ json: row });

for (const s of saleDetails) {
  out.push({ json: {
    _op: 'sale_detail',
    year: s.year, broker: s.broker, ticker: s.ticker,
    sell_date: s.sell_date, purchase_date: s.purchase_date, qty: s.qty,
    cost_czk: Math.round(s.cost_czk * 100) / 100,
    proceeds_czk: Math.round(s.proceeds_czk * 100) / 100,
    time_test_passed: s.time_test_passed,
  }});
}

return out;

