if (s.sales.length) {
  msg += `\n${T.sales(s.sales.length)}\n`;
  for (const sale of s.sales.slice(0, MAX_SALES_SHOWN)) {
    const flag = sale.time_test_passed ? T.passed : '⚠️';
    msg += `• ${sale.ticker}: ${sale.bought} → ${sale.sold}, ${fmt(sale.gain_czk)} CZK ${flag}\n`;
  }
  if (s.sales.length > MAX_SALES_SHOWN) msg += T.more(s.sales.length - MAX_SALES_SHOWN) + '\n';
}

for (const y of s.years) {
  msg += `\n📅 <b>${y.year}</b>\n`;
  if (y.sales_count) msg += T.fileSales(fmt(y.this_import_revenue_czk), fmt(y.this_import_gain_czk)) + '\n';
