  if (y.this_import_interest_czk) msg += T.fileInt(fmt(y.this_import_interest_czk)) + '\n';
  msg += T.ytd(fmt(y.ytd_revenue_czk));
  msg += y.exemption_still_possible ? T.left(fmt(y.ytd_remaining_to_100k)) : T.over(y.year);
  msg += T.ytdDiv(fmt(y.ytd_dividend_czk), fmt(y.ytd_withholding_czk));
  msg += y.ytd_interest_czk ? T.ytdInt(fmt(y.ytd_interest_czk)) : `\n`;
}

