// n8n Code node: "Check period overlap"
// Place right after "Parse Import". Compares this file's period with periods already
// imported for the SAME broker (stored in FILE_UNIQUE_CZ_TAX by "Mark file processed").
// Output: one item { broker, period_from, period_to, overlap, clash_from, clash_to, text }
//   -> IF "Period overlap?" : true  -> "Notify period overlap" sends {{ $json.text }}, stop
//                             false -> Get existing lots (rest of the workflow)
// Two periods overlap if they share at least one day.
// Language: field "lang" in the "Config" node = "en" (default), "uk" or "cs"
const LANG = { uk: 'uk', cs: 'cs', cz: 'cs' }[String($('Config').first().json.lang || '').toLowerCase()] || 'en';

const meta = $('Parse Import').all().map(i => i.json).find(r => r.kind === 'meta');
if (!meta || !meta.period_from || !meta.period_to) {
  throw new Error('Could not determine the period of this file');
}

const done = $('Check processed files').all().map(i => i.json)
  .filter(r => r.broker === meta.broker && r.period_from && r.period_to);

const clash = done.find(r => meta.period_from <= r.period_to && meta.period_to >= r.period_from);

const text = !clash ? '' : ({
  en: `⛔ File not processed: ${meta.broker} ${meta.period_from} → ${meta.period_to} overlaps an already imported period ${clash.period_from} → ${clash.period_to}.\nExport a statement that starts after ${clash.period_to}.`,
  uk: `⛔ Файл не оброблено: ${meta.broker} ${meta.period_from} → ${meta.period_to} перекривається з уже імпортованим періодом ${clash.period_from} → ${clash.period_to}.\nВивантаж виписку, що починається після ${clash.period_to}.`,
  cs: `⛔ Soubor nebyl zpracován: ${meta.broker} ${meta.period_from} → ${meta.period_to} se překrývá s již importovaným obdobím ${clash.period_from} → ${clash.period_to}.\nStáhněte výpis, který začíná po ${clash.period_to}.`,
})[LANG];

return [{ json: {
  broker: meta.broker,
  period_from: meta.period_from,
  period_to: meta.period_to,
  period_source: meta.period_source,
  overlap: Boolean(clash),
  clash_from: clash ? clash.period_from : null,
  clash_to: clash ? clash.period_to : null,
  text,
}}];

