const years = {};
const Y = y => (years[y] ||= { revenue: 0, taxableGain: 0, exemptGain: 0, dividend: 0, withholding: 0, interest: 0, count: 0 });
for (const s of sales) {
  const t = Y(num(s.year));
  const g = num(s.proceeds_czk) - num(s.cost_czk);
  t.revenue += num(s.proceeds_czk); t.count += 1;
  if (exempt(s)) t.exemptGain += g; else t.taxableGain += g;
}
for (const r of ytd) {
  const t = Y(num(r.year));
  t.dividend += num(r.dividend_czk);
  t.withholding += num(r.withholding_czk);
  t.interest += num(r.interest_czk);
}

function estimate(t) {
  const over = t.revenue > LIMIT_CZK;
  const salesTax = over ? Math.max(0, t.taxableGain) * RATE : 0;
  const divTax = t.dividend * RATE;
  const credit = Math.min(Math.abs(t.withholding), divTax);
  const interestTax = t.interest * RATE;   // no tax withheld on T212 interest
  return { over, salesTax, divTax: Math.max(0, divTax - credit), credit, interestTax };
}

function tickerTable(list) {
  const by = {};
  for (const s of list) {
    const k = `${s.broker}|${s.ticker}`;
    const t = (by[k] ||= { broker: s.broker, ticker: s.ticker, gain: 0, count: 0 });
    t.gain += num(s.proceeds_czk) - num(s.cost_czk); t.count += 1;
  }
  return Object.values(by).sort((a, b) => b.gain - a.gain);
}

function brokerLine(rows) {
  const by = {};
  for (const t of rows) by[t.broker] = (by[t.broker] || 0) + t.gain;
  return Object.entries(by).map(([b, g]) => `${b} ${sign(g)}`).join(', ');
}

let msg = '';

if (yearMode) {
  // ================= ONE YEAR =================
  const year = Number(arg);
  const t = years[year];
  msg += T.yearTitle(year) + '\n';
  if (!t) {
    msg += '\n' + T.noData(year);
  } else {
    const e = estimate(t);
    msg += `\n${T.sales(t.count)}\n`;
    msg += T.revenue(fmt(t.revenue), e.over) + '\n';
    msg += T.taxableGain(sign(t.taxableGain)) + '\n';
    if (t.exemptGain) msg += T.exemptGain(sign(t.exemptGain)) + '\n';
    msg += (e.over ? T.toTax(fmt(Math.max(0, t.taxableGain))) : T.exempt) + '\n';

    msg += `\n${T.dividends}\n`;
    msg += T.divLine(fmt(t.dividend), fmt(Math.abs(t.withholding))) + '\n';
    if (t.interest) msg += `\n${T.interest}\n${fmt(t.interest)} CZK\n`;

    msg += `\n${T.estimate}\n`;
    msg += T.fromSales(fmt(e.salesTax)) + '\n';
    msg += T.fromDiv(fmt(t.dividend * RATE), fmt(e.credit), fmt(e.divTax)) + '\n';
    if (t.interest) msg += T.fromInt(fmt(e.interestTax)) + '\n';
    msg += T.total(fmt(e.salesTax + e.divTax + e.interestTax)) + '\n';
    msg += T.disclaimer + '\n';

    const rows = tickerTable(sales.filter(s => num(s.year) === year));
    if (rows.length) {
      msg += `\n${T.byTicker}\n`;
      for (const r of rows) msg += `${r.gain >= 0 ? '🟢' : '🔴'} ${esc(r.ticker)} (${r.broker}): ${sign(r.gain)} CZK\n`;
      msg += T.byBroker(brokerLine(rows)) + '\n';
    }
  }
} else {
  // ================= FULL REPORT =================
  msg += `${T.fullTitle}\n\n${T.byYear}\n`;
  const tot = { gain: 0, dividend: 0, withholding: 0, interest: 0, tax: 0 };
  for (const y of Object.keys(years).map(Number).sort()) {
    const t = years[y], e = estimate(t);
    msg += T.yearLine(y, sign(t.taxableGain + t.exemptGain), fmt(t.dividend));
    if (t.interest) msg += T.yInt(fmt(t.interest));
    msg += T.yRest(fmt(t.revenue), e.over ? '⚠️' : '✅', fmt(e.salesTax + e.divTax + e.interestTax)) + '\n';
    tot.gain += t.taxableGain + t.exemptGain; tot.dividend += t.dividend; tot.interest += t.interest;
    tot.withholding += Math.abs(t.withholding); tot.tax += e.salesTax + e.divTax + e.interestTax;
  }
  msg += T.totLine(sign(tot.gain), fmt(tot.dividend), fmt(tot.interest), fmt(tot.withholding), fmt(tot.tax)) + '\n';

  const rows = tickerTable(sales);
  msg += `\n${T.tickers}\n`;
  if (!rows.length) msg += T.noSales + '\n';
  for (const r of rows) msg += `${r.gain >= 0 ? '🟢' : '🔴'} ${esc(r.ticker)} (${r.broker}): ${sign(r.gain)}\n`;
  if (rows.length) msg += T.byBroker(brokerLine(rows)) + '\n';

  const plus3 = d => { const x = new Date(d); x.setFullYear(x.getFullYear() + 3); return x.toISOString().slice(0, 10); };
  const pos = {};
  for (const l of lots) {
    const k = `${l.broker}|${l.ident}`;
    const p = (pos[k] ||= { broker: l.broker, ticker: l.ticker, qty: 0, cost: 0, currency: l.currency, first: l.purchase_date, last: l.purchase_date });
    p.qty += num(l.qty_remaining); p.cost += num(l.cost_native);
    if (l.purchase_date < p.first) p.first = l.purchase_date;
    if (l.purchase_date > p.last) p.last = l.purchase_date;
  }
  const open = Object.values(pos).sort((a, b) => a.first.localeCompare(b.first));
  msg += `\n${T.open}\n`;
  if (!open.length) msg += T.none + '\n';
  for (const p of open) {
    const from = plus3(p.first), all = plus3(p.last);
    msg += `• ${esc(p.ticker)} (${p.broker}): ${+p.qty.toFixed(4)} ${T.pcs}, ${fmt(p.cost)} ${p.currency} · `;
    msg += (from === all ? T.from(from) : T.firstAll(from, all)) + '\n';
  }
  msg += '\n' + T.details(new Date().getFullYear());
}

const MAX = 4096;
if (msg.length > MAX) msg = msg.slice(0, MAX - 40) + '\n' + T.cut;
return [{ json: { text: msg } }];

// n8n Code node: "Check if duplicate"
