const num = v => Number(v) || 0;
const fmt = n => Math.round(n).toLocaleString('cs-CZ');
const sign = n => (Math.round(n) > 0 ? '+' : '') + fmt(n);
const q = n => +Number(n).toFixed(6);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LIMIT_CZK = 100000, RATE = 0.15;
const today = new Date().toISOString().slice(0, 10);
const year = Number(today.slice(0, 4));
const plus3 = d => { const x = new Date(d); x.setFullYear(x.getFullYear() + 3); return x.toISOString().slice(0, 10); };
const reply = text => [{ json: { text } }];

// ---------- parse command ----------
const parts = String($('Telegram Trigger').first().json.message.text || '').trim().split(/\s+/).slice(1);
const brokerArg = parts.find(p => /^(t212|ibkr)$/i.test(p));
const curArg = parts.find(p => /^(czk|eur|usd|gbp|chf)$/i.test(p));
const rest = parts.filter(p => p !== brokerArg && p !== curArg);
const [tickerArg, qtyArg, priceArg] = rest;
if (!tickerArg) return reply(T.help);

// ---------- lots of this position (FIFO order) ----------
const allLots = $('Report: get lots').all().map(i => i.json).filter(l => l.ident && num(l.qty_remaining) > 0);
let lots = allLots.filter(l => [l.ticker, l.ident].some(x => String(x).toUpperCase() === tickerArg.toUpperCase()));
if (brokerArg) lots = lots.filter(l => l.broker.toUpperCase() === brokerArg.toUpperCase());
const brokers = [...new Set(lots.map(l => l.broker))];
if (!lots.length) return reply(T.noPos(esc(tickerArg)) + T.help);
if (brokers.length > 1) return reply(T.twoBrokers(esc(tickerArg), brokers.join(' & '), brokers[0]));
lots.sort((a, b) => String(a.purchase_date).localeCompare(String(b.purchase_date)));
const broker = brokers[0];
const ticker = lots[0].ticker;
const lotCur = lots[0].currency;
const held = lots.reduce((s, l) => s + num(l.qty_remaining), 0);

// ---------- tax-free quantity today ----------
let freeQty = 0;
for (const l of lots) { if (plus3(l.purchase_date) <= today) freeQty += num(l.qty_remaining); else break; }
const nextFree = lots.find(l => plus3(l.purchase_date) > today);

if (/^free$/i.test(qtyArg || '')) {
  let t = T.hold(esc(ticker), broker, q(held));
  t += freeQty > 0 ? T.freeNow(q(freeQty)) : T.noneFree;
  if (nextFree) t += T.nextFree(q(nextFree.qty_remaining), plus3(nextFree.purchase_date));
  t += T.allFree(plus3(lots[lots.length - 1].purchase_date));
  return reply(t);
}

const qty = /^all$/i.test(qtyArg || '') ? held : num(String(qtyArg).replace(',', '.'));
const price = num(String(priceArg).replace(',', '.'));
if (!(qty > 0) || !(price > 0)) return reply(T.help);
if (qty > held + 1e-9) return reply(T.onlyHave(q(held), esc(ticker), broker));

// ---------- CNB rates (latest for the sale, nearest cached for purchases) ----------
const rates = {};   // currency -> [{date, rate}]
for (const r of $('Report: get rates').all().map(i => i.json)) {
  if (!r.date || !r.currency) continue;
  (rates[r.currency] ||= []).push({ date: r.date, rate: num(r.rate) });
}
for (const c in rates) rates[c].sort((a, b) => a.date.localeCompare(b.date));
let approx = false;
function rateOn(date, cur) {
  if (cur === 'CZK') return 1;
  const list = rates[cur];
  if (!list || !list.length) throw new Error(`No CNB rates for ${cur} in cnb_rate_cache`);
  const exact = list.find(r => r.date === date);
  if (exact) return exact.rate;
  approx = true;
  const t = new Date(date).getTime();
  return list.reduce((best, r) => Math.abs(new Date(r.date) - t) < Math.abs(new Date(best.date) - t) ? r : best).rate;
}
const latest = cur => (cur === 'CZK' ? 1 : rates[cur]?.[rates[cur].length - 1]?.rate);
const priceCur = (curArg || lotCur).toUpperCase();
if (!latest(priceCur) || !latest(lotCur)) return reply(T.noRate(priceCur, lotCur));
const priceCzk = price * latest(priceCur);              // per share, CZK

// ---------- FIFO simulation ----------
let need = qty;
const used = [];
for (const l of lots) {
  if (need <= 1e-9) break;
  const take = Math.min(num(l.qty_remaining), need);
  const costCzk = num(l.cost_native) / num(l.qty_remaining) * take * rateOn(l.purchase_date, l.currency);
  const free = plus3(l.purchase_date) <= today;
  used.push({ date: l.purchase_date, qty: take, costCzk, proceedsCzk: take * priceCzk, free, freeFrom: plus3(l.purchase_date) });
  need -= take;
}
const exemptPart = used.filter(u => u.free), taxablePart = used.filter(u => !u.free);
const sum = (list, k) => list.reduce((s, u) => s + u[k], 0);
const revenue = sum(used, 'proceedsCzk');
const gainExempt = sum(exemptPart, 'proceedsCzk') - sum(exemptPart, 'costCzk');
const gainTaxable = sum(taxablePart, 'proceedsCzk') - sum(taxablePart, 'costCzk');

// ---------- effect on this year's 100 000 CZK limit and tax ----------
const ytdRow = $('Report: get ytd').all().map(i => i.json).find(r => num(r.year) === year) || {};
const revBefore = num(ytdRow.sales_revenue_czk);
const gainBefore = $('Report: get sales').all().map(i => i.json)
  .filter(s => num(s.year) === year && !(s.time_test_passed === true || s.time_test_passed === 'true'))
  .reduce((s, r) => s + num(r.proceeds_czk) - num(r.cost_czk), 0);
const revAfter = revBefore + revenue;
const taxBefore = revBefore > LIMIT_CZK ? Math.max(0, gainBefore) * RATE : 0;
const taxAfter = revAfter > LIMIT_CZK ? Math.max(0, gainBefore + gainTaxable) * RATE : 0;
const extraTax = taxAfter - taxBefore;

// ---------- message ----------
let t = T.title(q(qty), esc(ticker), broker);
t += T.price(price, priceCur, fmt(priceCzk), fmt(revenue));
t += T.lots;
for (const u of used.slice(0, 15)) {
  t += `${u.free ? '✅' : '⏳'} ${u.date}: ${q(u.qty)} ${T.pcs}, ${sign(u.proceedsCzk - u.costCzk)} CZK`;
  t += u.free ? T.lotExempt : T.lotFreeFrom(u.freeFrom);
}
if (used.length > 15) t += T.moreLots(used.length - 15);

t += `\n${T.gain}`;
if (exemptPart.length) t += T.gainExempt(q(sum(exemptPart, 'qty')), sign(gainExempt));
if (taxablePart.length) t += T.gainTaxable(q(sum(taxablePart, 'qty')), sign(gainTaxable));

t += `\n${T.limit(year)}`;
t += T.limitLine(fmt(revBefore), fmt(revAfter));
t += revAfter > LIMIT_CZK ? ` ⚠️\n` : T.limitLeft(fmt(LIMIT_CZK - revAfter));
if (revBefore <= LIMIT_CZK && revAfter > LIMIT_CZK && gainBefore > 0) t += T.crossing(year, sign(gainBefore));

t += T.tax(extraTax > 0 ? fmt(extraTax) : extraTax < 0 ? '−' + fmt(-extraTax) + T.lowers : '0');

if (taxablePart.length && gainTaxable > 0) {
  t += T.wait(taxablePart[taxablePart.length - 1].freeFrom);
  if (freeQty > 0) t += T.canFree(q(freeQty));
}
if (approx) t += T.approx;
t += T.note;

return reply(t.length > 4096 ? t.slice(0, 4050) + T.cut : t);

// n8n Code node: "Build DAP summary"   (command /dap 2026 or /tax 2026)
// Totals for one tax year, grouped the way the Czech tax return (DAP) asks for them.
// Reads: $('Report: get sales').all()   tax_sales
//        $('Report: get income').all()  tax_income  (dividends / withholding / interest, one row each)
// Output: one item { text } for Telegram (HTML)
// Language: field "lang" in the "Config" node = "en" (default), "uk" or "cs"
const LANG = { uk: 'uk', cs: 'cs', cz: 'cs' }[String($('Config').first().json.lang || '').toLowerCase()] || 'en';
const T = {
  en: {
    title: y => `🧾 <b>Tax return summary for ${y}</b>`,
    s10: '<b>1. Sale of securities — § 10 (Příloha č. 2)</b>',
    noSales: 'No sales.',
    exemptLimit: v => `Proceeds ${v} CZK ≤ 100 000 → <b>exempt</b>, not reported.`,
    income: v => `Příjmy (income): <b>${v} CZK</b>`,
    costs: v => `Výdaje (cost + fees): <b>${v} CZK</b>`,
    diff: v => `Rozdíl (difference): <b>${v} CZK</b>`,
    loss: ' → loss, tax base = 0 (cannot be carried forward)',
    deals: n => `Number of trades: ${n}`,
    timeExempt: (n, r, g) => `Exempt under the 3-year test: ${n} trades, proceeds ${r} CZK, gain ${g} CZK — not reported.`,
    s8div: '<b>2. Foreign dividends — § 8</b>',
    noDiv: 'No dividends.',
    country: (c, g, w, cr, pay) => `<b>${c}</b>: gross ${g} CZK, withheld ${w} CZK, creditable max ${cr} CZK → to pay ${pay} CZK`,
    adr: '<i>Country is taken from the ISIN; for ADRs (SHEL, TM…) the paying country may differ.</i>',
    s8int: '<b>3. Interest — § 8</b>',
    intLine: v => `${v} CZK (no tax withheld)`,
    noInt: 'None.',
    total: v => `<b>Estimated tax: ≈ ${v} CZK</b>`,
    parts: (a, b, c) => `(sales ${a} + dividends ${b} + interest ${c})`,
    footer: y => `<i>Where exactly to report dividends and interest (general base or separate base under § 16a, Příloha č. 3/4) — check the official "Pokyny k vyplnění" for ${y}. Not tax advice. Full detail: /export ${y}</i>`,
    cut: '\n… truncated.',
  },
  uk: {
    title: y => `🧾 <b>Підсумки для декларації за ${y}</b>`,
    s10: '<b>1. Продаж цінних паперів — § 10 (Příloha č. 2)</b>',
    noSales: 'Продажів не було.',
    exemptLimit: v => `Виручка ${v} CZK ≤ 100 000 → <b>звільнено</b>, у декларацію не вписується.`,
    income: v => `Příjmy (виручка): <b>${v} CZK</b>`,
    costs: v => `Výdaje (собівартість + комісії): <b>${v} CZK</b>`,
    diff: v => `Rozdíl: <b>${v} CZK</b>`,
    loss: ' → збиток, база = 0 (на наступний рік не переноситься)',
    deals: n => `Кількість угод: ${n}`,
    timeExempt: (n, r, g) => `Звільнено за 3-річним тестом: ${n} угод, виручка ${r} CZK, прибуток ${g} CZK — не вписується.`,
    s8div: '<b>2. Дивіденди з-за кордону — § 8</b>',
    noDiv: 'Дивідендів не було.',
    country: (c, g, w, cr, pay) => `<b>${c}</b>: брутто ${g} CZK, утримано ${w} CZK, до зарахування max ${cr} CZK → доплата ${pay} CZK`,
    adr: '<i>Країна — за ISIN; для ADR (SHEL, TM…) країна платника може відрізнятися.</i>',
    s8int: '<b>3. Проценти — § 8</b>',
    intLine: v => `${v} CZK (податок не утримувався)`,
    noInt: 'Не було.',
    total: v => `<b>Орієнтовний податок: ≈ ${v} CZK</b>`,
    parts: (a, b, c) => `(продажі ${a} + дивіденди ${b} + проценти ${c})`,
    footer: y => `<i>Куди саме вписати дивіденди й проценти (загальний базис чи окремий за § 16a, Příloha č. 3/4) — звір з Pokyny k vyplnění за ${y}. Не податкова консультація. Детальний розрахунок: /export ${y}</i>`,
    cut: '\n… обрізано.',
  },
  cs: {
    title: y => `🧾 <b>Podklady pro daňové přiznání za ${y}</b>`,
    s10: '<b>1. Prodej cenných papírů — § 10 (Příloha č. 2)</b>',
    noSales: 'Žádné prodeje.',
    exemptLimit: v => `Příjmy ${v} CZK ≤ 100 000 → <b>osvobozeno</b>, neuvádí se.`,
    income: v => `Příjmy: <b>${v} CZK</b>`,
    costs: v => `Výdaje (pořizovací cena + poplatky): <b>${v} CZK</b>`,
    diff: v => `Rozdíl: <b>${v} CZK</b>`,
    loss: ' → ztráta, základ = 0 (nelze převést do dalších let)',
    deals: n => `Počet obchodů: ${n}`,
    timeExempt: (n, r, g) => `Osvobozeno časovým testem: ${n} obchodů, příjmy ${r} CZK, zisk ${g} CZK — neuvádí se.`,
    s8div: '<b>2. Zahraniční dividendy — § 8</b>',
    noDiv: 'Žádné dividendy.',
    country: (c, g, w, cr, pay) => `<b>${c}</b>: hrubé ${g} CZK, sraženo ${w} CZK, započitatelné max ${cr} CZK → doplatit ${pay} CZK`,
    adr: '<i>Země je určena podle ISIN; u ADR (SHEL, TM…) se může stát zdroje lišit.</i>',
    s8int: '<b>3. Úroky — § 8</b>',
    intLine: v => `${v} CZK (bez srážkové daně)`,
    noInt: 'Žádné.',
    total: v => `<b>Odhad daně: ≈ ${v} CZK</b>`,
    parts: (a, b, c) => `(prodeje ${a} + dividendy ${b} + úroky ${c})`,
    footer: y => `<i>Kam přesně uvést dividendy a úroky (obecný základ, nebo samostatný základ podle § 16a, Příloha č. 3/4) — ověřte v Pokynech k vyplnění za rok ${y}. Nejde o daňové poradenství. Podrobný výpočet: /export ${y}</i>`,
    cut: '\n… zkráceno.',
  },
}[LANG];

const num = v => Number(v) || 0;
const fmt = n => Math.round(n).toLocaleString('cs-CZ');
const LIMIT_CZK = 100000, RATE = 0.15;
const exempt = s => s.time_test_passed === true || s.time_test_passed === 'true';

const arg = String($('Telegram Trigger').first().json.message.text || '').trim().split(/\s+/)[1];
const year = /^\d{4}$/.test(arg || '') ? Number(arg) : new Date().getFullYear() - 1;

const sales = $('Report: get sales').all().map(i => i.json).filter(r => num(r.year) === year && r.ticker);
const income = $('Report: get income').all().map(i => i.json).filter(r => num(r.year) === year && r.type);

let t = T.title(year) + '\n';

// ---------- § 10: sale of securities ----------
const revenueAll = sales.reduce((s, r) => s + num(r.proceeds_czk), 0);
const taxable = sales.filter(r => !exempt(r));
const timeExempt = sales.filter(exempt);
const income10 = taxable.reduce((s, r) => s + num(r.proceeds_czk), 0);
const costs10 = taxable.reduce((s, r) => s + num(r.cost_czk), 0);
const base10 = income10 - costs10;

t += `\n${T.s10}\n`;
if (!sales.length) {
  t += T.noSales + '\n';
} else if (revenueAll <= LIMIT_CZK) {
  t += T.exemptLimit(fmt(revenueAll)) + '\n';
} else {
  t += T.income(fmt(income10)) + '\n';
  t += T.costs(fmt(costs10)) + '\n';
  t += T.diff(fmt(base10)) + (base10 < 0 ? T.loss : '') + '\n';
  t += T.deals(taxable.length) + '\n';
}
if (timeExempt.length) {
  const g = timeExempt.reduce((s, r) => s + num(r.proceeds_czk) - num(r.cost_czk), 0);
  t += T.timeExempt(timeExempt.length, fmt(timeExempt.reduce((s, r) => s + num(r.proceeds_czk), 0)), fmt(g)) + '\n';
}
const tax10 = revenueAll > LIMIT_CZK ? Math.max(0, base10) * RATE : 0;

// ---------- § 8: dividends by country ----------
const byCountry = {};
for (const r of income.filter(r => r.type === 'dividend' || r.type === 'withholding')) {
  const c = r.country || '??';
  const x = (byCountry[c] ||= { gross: 0, withheld: 0 });
  if (r.type === 'dividend') x.gross += num(r.amount_czk); else x.withheld -= num(r.amount_czk);
}
t += `\n${T.s8div}\n`;
let taxDiv = 0;
const countries = Object.entries(byCountry).sort((a, b) => b[1].gross - a[1].gross);
if (!countries.length) t += T.noDiv + '\n';
for (const [c, x] of countries) {
  const czTax = x.gross * RATE;
  const credit = Math.min(Math.max(0, x.withheld), czTax);
  taxDiv += czTax - credit;
  t += T.country(c, fmt(x.gross), fmt(x.withheld), fmt(credit), fmt(czTax - credit)) + '\n';
}
if (countries.length) t += T.adr + '\n';

// ---------- § 8: interest ----------
const interest = income.filter(r => r.type === 'interest').reduce((s, r) => s + num(r.amount_czk), 0);
t += `\n${T.s8int}\n`;
t += (interest ? T.intLine(fmt(interest)) : T.noInt) + '\n';
const taxInt = interest * RATE;

t += '\n' + T.total(fmt(tax10 + taxDiv + taxInt)) + '\n';
t += T.parts(fmt(tax10), fmt(taxDiv), fmt(taxInt)) + '\n';
t += '\n' + T.footer(year);

return [{ json: { text: t.length > 4096 ? t.slice(0, 4050) + T.cut : t } }];

// n8n Code node: "Build export"   (command /export 2026)
// Builds a CSV with every sale + every dividend / withholding / interest row of the year.
// Opens in Czech Excel directly (separator ';', decimal comma, UTF-8 BOM).
// Column names stay Czech in both languages - the file is evidence for the Czech tax office.
// Reads: $('Report: get sales').all()   tax_sales
//        $('Report: get income').all()  tax_income
// Output: one item with binary "data" (the CSV) + json.caption -> Telegram "Send Document"
// Language: field "lang" in the "Config" node = "en" (default), "uk" or "cs"
const LANG = { uk: 'uk', cs: 'cs', cz: 'cs' }[String($('Config').first().json.lang || '').toLowerCase()] || 'en';
const caption = (y, s, i) => ({
  en: `📎 Tax detail for ${y}: ${s} sales, ${i} income rows`,
  uk: `📎 Розрахунок за ${y}: ${s} продажів, ${i} рядків доходів`,
  cs: `📎 Výpočet za ${y}: ${s} prodejů, ${i} řádků příjmů`,
})[LANG];

const num = v => Number(v) || 0;
const dec = n => (Math.round(num(n) * 100) / 100).toFixed(2).replace('.', ',');
const qty = n => String(+num(n).toFixed(6)).replace('.', ',');
const cell = v => { const s = String(v ?? ''); return /[;"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const exempt = s => s.time_test_passed === true || s.time_test_passed === 'true';

const arg = String($('Telegram Trigger').first().json.message.text || '').trim().split(/\s+/)[1];
const year = /^\d{4}$/.test(arg || '') ? Number(arg) : new Date().getFullYear() - 1;

const sales = $('Report: get sales').all().map(i => i.json).filter(r => num(r.year) === year && r.ticker)
  .sort((a, b) => String(a.sell_date).localeCompare(String(b.sell_date)));
const income = $('Report: get income').all().map(i => i.json).filter(r => num(r.year) === year && r.type)
  .sort((a, b) => String(a.date).localeCompare(String(b.date)));

const header = ['typ', 'broker', 'ticker', 'isin_zeme', 'datum_nakupu', 'datum_prodeje_vyplaty', 'pocet',
  'castka_mena', 'mena', 'prijem_czk', 'vydaj_czk', 'zisk_czk', 'casovy_test', 'poznamka'];
const rows = [header];

for (const s of sales) {
  rows.push(['prodej', s.broker, s.ticker, '', s.purchase_date, s.sell_date, qty(s.qty), '', '',
    dec(s.proceeds_czk), dec(s.cost_czk), dec(num(s.proceeds_czk) - num(s.cost_czk)),
    exempt(s) ? 'ano' : 'ne', 'výdaj = pořizovací cena + poplatky']);
}
const typeName = { dividend: 'dividenda', withholding: 'srazkova_dan', interest: 'urok' };
for (const r of income) {
  rows.push([typeName[r.type] || r.type, r.broker, r.ticker, r.isin || r.country || '', '', r.date, '',
    dec(r.amount), r.currency, dec(r.amount_czk), '', '', '', r.note || '']);
}

// totals at the bottom
const sum = (list, f) => list.reduce((a, r) => a + f(r), 0);
const taxable = sales.filter(s => !exempt(s));
rows.push([]);
rows.push(['SOUCET prodeje (bez casoveho testu)', '', '', '', '', '', '', '', '',
  dec(sum(taxable, r => num(r.proceeds_czk))), dec(sum(taxable, r => num(r.cost_czk))),
  dec(sum(taxable, r => num(r.proceeds_czk) - num(r.cost_czk)))]);
rows.push(['SOUCET dividendy (brutto)', '', '', '', '', '', '', '', '', dec(sum(income.filter(r => r.type === 'dividend'), r => num(r.amount_czk)))]);
rows.push(['SOUCET srazkova dan', '', '', '', '', '', '', '', '', dec(sum(income.filter(r => r.type === 'withholding'), r => num(r.amount_czk)))]);
rows.push(['SOUCET uroky', '', '', '', '', '', '', '', '', dec(sum(income.filter(r => r.type === 'interest'), r => num(r.amount_czk)))]);

const csv = '﻿' + rows.map(r => r.map(cell).join(';')).join('\r\n');
const fileName = `dane_${year}.csv`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), fileName, 'text/csv');

return [{
  json: { caption: caption(year, sales.length, income.length), fileName },
  binary: { data: binary },
}];
